-- The QUICK-3-CHAM code key (Code keys -> Drilling -> QUICK-3-CHAM), from the ISCAR
-- e-catalog's QUICK-3-CHAM families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.quick3cham', $ck${"title": "QUICK-3-CHAM code key – drilling heads and drill bodies", "subtitle": "Exchangeable 3 flute drilling heads (H3P, F3P flat, F3B counterboring) and the D3N drill bodies that carry them", "example": "H3P 120-IQ", "decoder": "quick-3-cham", "sections": [{"key": "i-family", "title": "Head – family", "sample": "H3P", "rows": [{"code": "H3P", "meaning": "3 flute drilling heads for carbon and alloy steel (ISO P) and cast iron (ISO K)"}, {"code": "F3P", "meaning": "3 flute flat drilling heads for ISO P and ISO K materials"}, {"code": "F3B", "meaning": "3 flute counterboring heads"}]}, {"key": "i-dia", "title": "Head – drilling diameter", "sample": "120", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 120 = 12.0 mm)"}, {"code": "####", "meaning": "Drilling diameter x100 (e.g. 2381 = 23.81 mm)"}]}, {"key": "i-suffix", "title": "Head – suffix", "sample": "IQ", "rows": [{"code": "IQ", "meaning": "IQ line"}]}, {"key": "t-family", "title": "Drill body – family", "sample": "D3N", "rows": [{"code": "D3N", "meaning": "Exchangeable head 3 flute drill body with coolant holes"}]}, {"key": "t-dia", "title": "Drill body – head size", "rows": [{"code": "###", "meaning": "Smallest head diameter it carries x10 (e.g. 120 = 12.0 mm)"}]}, {"key": "t-length", "title": "Drill body – length", "rows": [{"code": "###", "meaning": "Usable length in mm (inferred)"}]}, {"key": "t-height", "title": "Drill body – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (16, 20, 25, 32)"}]}, {"key": "t-shank", "title": "Drill body – shank type", "rows": [{"code": "A", "meaning": "One flat shank"}, {"code": "R", "meaning": "Round (cylindrical) shank"}]}, {"key": "t-depth", "title": "Drill body – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth as a ratio of the diameter (e.g. 3D = 3xD)"}, {"code": "##D", "meaning": "Drilling depth ratio (10D = 10xD)"}, {"code": "#.#D", "meaning": "Drilling depth ratio (1.5D = 1.5xD)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
